contracts/simple/LastClaimWins.vy.content:
#pragma version ^0.4.3

"""
@title LastClaimWins
@notice Reusable last-claim-wins game with no token custody or transfers.
"""


event GameStarted:
    game_id: indexed(uint256)
    deadline: uint256

event Claimed:
    game_id: indexed(uint256)
    claimer: indexed(address)
    claimed_at: uint256


admin: public(immutable(address))
game_id: public(uint256)
deadline: public(HashMap[uint256, uint256])
last_claimer: public(HashMap[uint256, address])
last_claim_at: public(HashMap[uint256, uint256])


@deploy
def __init__():
    """
    @notice Sets the deployer as the permanent game administrator.
    """
    admin = msg.sender


@external
def start(_deadline: uint256):
    """
    @notice Starts the next game with a fixed Unix timestamp deadline.
    @param _deadline Final timestamp at which calls to `this_is_mine()` count.
    """
    assert msg.sender == admin, "not admin"
    assert (
        self.game_id == 0
        or block.timestamp > self.deadline[self.game_id]
    ), "game active"
    assert _deadline > block.timestamp, "bad deadline"

    self.game_id += 1
    self.deadline[self.game_id] = _deadline

    log GameStarted(game_id=self.game_id, deadline=_deadline)


@external
def this_is_mine():
    """
    @notice Records the caller as the current claimer for the active game.
    """
    assert self.game_id > 0, "no game"
    assert block.timestamp <= self.deadline[self.game_id], "expired"

    self.last_claimer[self.game_id] = msg.sender
    self.last_claim_at[self.game_id] = block.timestamp

    log Claimed(
        game_id=self.game_id,
        claimer=msg.sender,
        claimed_at=block.timestamp,
    )


@external
@view
def is_active(_game_id: uint256) -> bool:
    """
    @notice Returns true when the requested game is the current live game.
    """
    return (
        _game_id > 0
        and _game_id == self.game_id
        and block.timestamp <= self.deadline[_game_id]
    )


@external
@view
def is_expired(_game_id: uint256) -> bool:
    """
    @notice Returns true when the requested game exists and its deadline passed.
    """
    return (
        _game_id > 0
        and _game_id <= self.game_id
        and block.timestamp > self.deadline[_game_id]
    )
